package com.luxe.store.service;
import com.luxe.store.model.Usuario; import com.luxe.store.repository.UsuarioRepository; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UsuarioService { @Autowired private UsuarioRepository usuarioRepository; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public List<Usuario> obtenerTodos(){return usuarioRepository.findAll();} public Optional<Usuario> autenticar(String usuario,String contrasena){return usuarioRepository.findByUsuarioIgnoreCase(usuario).filter(u->"Activo".equalsIgnoreCase(u.getEstado())).filter(u->u.getContrasena()!=null&&encoder.matches(contrasena,u.getContrasena()));} }